@startuml

class EBike {
  + modelNumber : string
}

class Frame {
  + material : string
}

class DriveSystem {
  + maxTorque : double
}

class Motor {
  + powerOutput : double
}

class Controller {
  + currentState : ControllerState
}

class Battery {
  + storedEnergyWh : double
}

class BasicController {}

class AdvancedController {
  + nextInspectionDate : date
}

enum ControllerState {
  On
  Off
  Charging
}

EBike "1" *-- "1" Frame
EBike "1" *-- "1" DriveSystem
EBike "1" *-- "1" Controller
Frame "1" *-- "2" Wheel
DriveSystem "1" *-- "1" Motor
EBike "0..1" o-- "1" Battery
Controller "1" --> "0..1" Battery
Controller "1" --> "1" DriveSystem
BasicController --|> Controller
AdvancedController --|> Controller

class Wheel {}

@enduml

